    // ── Edits made in an editor ─────────────────────────────────────

    async function loadEditsPage() {
        const list = document.getElementById('editsList');
        if (!list) return;
        if (!state.currentProject) { list.innerHTML = '<p class="text-muted">Open a project to see its edits.</p>'; return; }
        try {
            const r = await api(`/projects/${state.currentProject.id}/edits`);
            state.edits = r.edits || [];
            list.innerHTML = state.edits.length ? state.edits.map(editCardHtml).join('')
                : '<p class="text-muted">No edit yet. Export your cut from Premiere and import it with the button above.</p>';
        } catch (err) {
            list.innerHTML = `<p class="text-sm" style="color:var(--danger,#e66);">The edits could not be read: ${esc(err.message)}</p>`;
        }
    }

    function editCardHtml(e) {
        const c = e.cut;
        const facts = [mwTime(e.duration_ms), e.frame_rate ? `${Math.round(e.frame_rate * 1000) / 1000} fps` : '',
            e.width ? `${e.width}×${e.height}` : '', e.has_audio ? 'with sound' : 'no sound', e.size_bytes ? fmtBytes(e.size_bytes) : '']
            .filter(Boolean).join(' · ');
        const cutLine = c
            ? `<strong>${c.summary.events}</strong> events in “${esc(c.sequence || '')}”, <strong>${c.summary.matched}</strong> of them Film Engine shots`
              + ` (${c.summary.by.file} by file, ${c.summary.by.code} by shot code)`
              + (c.summary.unmatched ? ` · not ours: ${esc(c.summary.unmatched_names.slice(0, 6).join(', '))}${c.summary.unmatched > 6 ? '…' : ''}` : '')
              + (c.summary.shots_not_in_cut.length ? ` · shots not in this cut: ${esc(c.summary.shots_not_in_cut.slice(0, 8).join(', '))}${c.summary.shots_not_in_cut.length > 8 ? '…' : ''}` : '')
            : 'No cut yet — add the XML or EDL this edit was exported with, so the score knows which shot plays where.';
        const rows = c ? c.events.map(ev => `<tr>
                <td style="padding:2px 8px 2px 0;">${mwTime(ev.start_ms)}</td>
                <td style="padding:2px 8px;">${mwTime(ev.duration_ms)}</td>
                <td style="padding:2px 8px;"><strong>${esc(ev.shot_code || '—')}</strong></td>
                <td style="padding:2px 8px;">${esc(ev.name || ev.file_name || '')}</td>
                <td style="padding:2px 0;" class="text-muted">${esc(ev.matched_by ? 'by ' + ev.matched_by : 'not a Film Engine shot')}</td></tr>`).join('') : '';
        return `<div class="card mb-16" data-edit-id="${esc(e.id)}">
            <div class="flex-between">
                <h3 style="margin:0;">v${esc(e.version)} · ${esc(e.name || '')}${e.is_latest ? ' <span class="badge">latest</span>' : ''}</h3>
                <div class="btn-row" style="margin:0;">
                    <button class="btn btn-primary btn-sm" onclick="scoreThisEdit(${jsAttr(e.id)}, ${e.version})">Score this edit</button>
                    <label class="btn btn-secondary btn-sm" style="cursor:pointer;margin:0;">${c ? 'Replace XML / EDL' : 'Add XML / EDL'}
                        <input type="file" accept=".xml,.edl,application/xml,text/xml,text/plain" style="display:none" onchange="importEditCut(${jsAttr(e.id)}, this)">
                    </label>
                    ${c ? `<button class="btn btn-secondary btn-sm" onclick="rematchEditCut(${jsAttr(e.id)})">Re-match shots</button>` : ''}
                    <button class="btn btn-secondary btn-sm" onclick="renameEdit(${jsAttr(e.id)})">Rename</button>
                    <button class="btn btn-secondary btn-sm" onclick="deleteEditVersion(${jsAttr(e.id)}, ${e.version})">Delete</button>
                </div>
            </div>
            <div class="text-sm text-muted" style="margin:4px 0 8px;">${facts}</div>
            ${e.available && e.video_url ? `<video src="${esc(API_BASE + e.video_url)}" controls preload="metadata" playsinline style="width:100%;max-height:40vh;background:#000;display:block;"></video>`
              : '<p class="text-sm" style="color:var(--danger,#e66);">The picture file is missing from the project folder.</p>'}
            <div class="text-sm" style="margin-top:8px;">${cutLine}</div>
            ${e.sessions.length ? `<div class="text-sm" style="margin-top:4px;">Scored in: ${e.sessions.map(x => `<a href="#" onclick="openScoreSession(${jsAttr(x.id)});return false;">${esc(x.name || 'untitled')}</a> (${esc(x.status)})`).join(', ')}</div>` : ''}
            ${e.file_path ? `<div class="text-sm text-muted" style="margin-top:4px;user-select:all;">${esc(e.file_path)}</div>` : ''}
            ${rows ? `<details style="margin-top:8px;"><summary class="text-sm">The cut, event by event</summary>
                <table class="text-sm" style="border-collapse:collapse;margin-top:6px;">${rows}</table></details>` : ''}
        </div>`;
    }
    async function importEditFile(input) {
        const file = input.files && input.files[0];
        if (!file || !state.currentProject) return;
        const out = document.getElementById('editImportProgress');
        const label = document.getElementById('editImportLabel');
        const say = t => { if (out) out.textContent = t; };
        if (label) label.classList.add('disabled');
        try {
            const opened = await api('/uploads', { method: 'POST', body: JSON.stringify({ total_bytes: file.size, mime: file.type || 'application/octet-stream', name: file.name }) });
            let at = 0, failures = 0;
            while (at < file.size) {
                const piece = file.slice(at, Math.min(file.size, at + EDIT_CHUNK));
                // The whole edit has no ceiling — it travels in pieces — but each
                // piece does, and one over it is refused here rather than as a 413.
                checkUploadSize(piece, `/uploads/${opened.id}`);
                try {
                    const res = await fetch(`${API_BASE}/uploads/${opened.id}`, {
                        method: 'PUT', headers: { 'Content-Type': 'application/octet-stream', 'X-Upload-Offset': String(at) }, body: piece,
                    });
                    const body = await res.json().catch(() => ({}));
                    if (!res.ok) throw new Error(body.error || `HTTP ${res.status}`);
                    at = body.received; failures = 0;
                } catch (err) {
                    if (++failures > 5) throw err;
                    // Ask the server where it got to, and carry on from there.
                    const st = await api(`/uploads/${opened.id}`).catch(() => null);
                    if (st) at = st.received;
                    await new Promise(r => setTimeout(r, 1000 * failures));
                }
                say(`Uploading ${file.name}: ${Math.floor(at / file.size * 100)}% of ${fmtBytes(file.size)}`);
            }
            say('Measuring the picture…');
            const r = await api(`/projects/${state.currentProject.id}/edits/import`, { method: 'POST', body: JSON.stringify({ upload_id: opened.id, name: file.name.replace(/\.[^.]+$/, '') }) });
            say(`Imported as edit v${r.edit.version} (${mwTime(r.edit.duration_ms)}). Add the XML or EDL it was exported with to see which shot plays where.`);
            loadEditsPage();
        } catch (err) {
            say(`${file.name} was not imported: ${err.message}`);
        } finally {
            if (label) label.classList.remove('disabled');
            input.value = '';
        }
    }

    async function importEditCut(editId, input) {
        const file = input.files && input.files[0];
        if (!file) return;
        try {
            checkUploadSize(file, `/edits/${editId}/cut`);
            const text = await file.text();
            const r = await api(`/edits/${editId}/cut`, { method: 'POST', body: JSON.stringify({ text, name: file.name }) });
            const sm = r.edit.cut.summary;
            setStatus(`${file.name}: ${sm.events} events, ${sm.matched} matched to shots${sm.unmatched ? `, ${sm.unmatched} not ours` : ''}`);
            loadEditsPage();
        } catch (err) { setStatus(`${file.name} was not read: ${err.message}`); }
        finally { input.value = ''; }
    }

    async function rematchEditCut(editId) {
        try { await api(`/edits/${editId}/cut/rematch`, { method: 'POST', body: '{}' }); loadEditsPage(); setStatus('Matched against the shots as they are now'); }
        catch (err) { setStatus('Could not re-match: ' + err.message); }
    }

    async function renameEdit(editId) {
        const e = (state.edits || []).find(x => x.id === editId);
        const name = prompt('Name this version', e ? e.name : '');
        if (name === null) return;
        try { await api(`/edits/${editId}`, { method: 'PUT', body: JSON.stringify({ name }) }); loadEditsPage(); }
        catch (err) { setStatus('Could not rename: ' + err.message); }
    }

    async function deleteEditVersion(editId, version) {
        if (!confirm(`Delete edit v${version}?\n\nThe files move to 05 Edit/deleted, so they can be recovered by hand.`)) return;
        try { await api(`/edits/${editId}`, { method: 'DELETE' }); loadEditsPage(); setStatus(`Edit v${version} deleted`); }
        catch (err) {
            // Refused while a score is written against it: say so, and offer the choice.
            if (/written against this edit/.test(err.message) && confirm(err.message + '\n\nDelete anyway and leave those scores with no picture?')) {
                try { await api(`/edits/${editId}?force=true`, { method: 'DELETE' }); loadEditsPage(); } catch (e2) { setStatus('Could not delete: ' + e2.message); }
            } else setStatus('Not deleted: ' + err.message);
        }
    }

    /** Open a score session timed to this edit, and go to it. */
    async function scoreThisEdit(editId, version) {
        try {
            const out = await api(`/projects/${state.currentProject.id}/music-sessions`, {
                method: 'POST', body: JSON.stringify({ edit_id: editId, name: `Score — edit v${version}` }),
            });
            MW.session = out.session;
            navigateTo('musicws');
        } catch (err) { setStatus('Could not open a score for this edit: ' + err.message); }
    }

    function openScoreSession(sessionId) { MW.session = { id: sessionId }; navigateTo('musicws'); }
